import { Component } from '@angular/core';
import { UsuarioService } from 'src/app/services/usuario.service';

@Component({
  selector: 'app-ejercicio19',
  templateUrl: './ejercicio19.component.html',
  styleUrls: ['./ejercicio19.component.css']
})
export class Ejercicio19Component {

  productName: string = '';
  userEmail: string = '';

  constructor(private usuarioService: UsuarioService) {}

  ngOnInit() {
    this.userEmail = this.usuarioService.obtenerEmailUsuarioLogeado(); // Asumiendo que este método ya está implementado y disponible
  }

  sendProductName() {
    // Cuando el usuario haga clic en el botón, el nombre del producto ya estará vinculado mediante [(ngModel)]
    // y userEmail está listo para ser usado.
  }

}
<!-- ejercicio19.component.html -->
<input [(ngModel)]="productName" placeholder="Introduzca el nombre del producto">
<button (click)="sendProductName()">Buscar</button>

<!-- Pasar el productName y userEmail al componente hijo -->
<app-componente-hijo [productName]="productName" [userEmail]="userEmail"></app-componente-hijo>
